export namespace OpencutProjectSummaryOutput {
/**
 * New and Classic-imported projects use ClassicGlobal. LegacyPerScene is an
 * explicit preservation profile for heterogeneous old Rust projects, never a
 * hidden override of Classic settings. Converting its scope is a separate edit.
 */
  export type SettingsProfile =
  | {
      profile: 'classic_global';
      settings: ProjectSettings;
    }
  | {
      formats: LegacySequenceFormat[];
      profile: 'legacy_per_scene';
    };
  export type Background =
  | {
      color: Color;
      kind: 'color';
    }
  | {
      intensity: number;
      kind: 'main_track_blur';
    };
  export type ColorEncoding = 'srgb' | 'linear_srgb';
  export type CanvasSizeMode = 'preset' | 'custom';

  export interface Response {
  data?: ProjectSummaryPage | null;
  error?: EditorError | null;
  request_id: string;
  warnings: string[];
  [k: string]: any;
}
  export interface ProjectSummaryPage {
  asset_count: number;
  default_sequence_id: string;
  font_count: number;
  name: string;
  next_sequence_offset?: number | null;
  project_id: string;
  revision: string;
  sequence_count: number;
  sequences: SequenceSummaryPage[];
  settings: SettingsProfile;
}
  export interface SequenceSummaryPage {
  authored_duration: Time;
  bookmark_count: number;
  caption_count: number;
  element_count: number;
  main_track_id: string;
  name: string;
  sequence_id: string;
  track_count: number;
  transition_count: number;
}
/**
 * Extent of authored elements and captions, including disabled content.
 * Bookmarks do not extend the content duration. This is not render admission.
 */
  export interface Time {
  ticks: string;
  timebase: number;
}
  export interface ProjectSettings {
  background: Background;
  canvas_size: CanvasSize;
  canvas_size_mode: CanvasSizeMode;
  fps: FrameRate;
  last_custom_canvas_size?: CanvasSize | null;
  original_canvas_size?: CanvasSize | null;
}
  export interface Color {
  /**
   * Straight alpha, independent of RGB encoding.
   */
  alpha: number;
  blue: number;
  encoding: ColorEncoding;
  green: number;
  red: number;
}
  export interface CanvasSize {
  height: number;
  width: number;
}
  export interface FrameRate {
  denominator: number;
  numerator: number;
}
  export interface LegacySequenceFormat {
  background: Background;
  canvas_size: CanvasSize;
  fps: FrameRate;
  sequence_id: string;
}
  export interface EditorError {
  code: string;
  details: any;
  message: string;
}

}

