export namespace OpencutTimelinePastePlanInput {
  export type SceneTrackKind = 'video' | 'audio' | 'text' | 'graphic' | 'effect' | 'caption';
  export type ClipboardTrackTarget =
  | {
      kind: 'existing';
      track_id: string;
    }
  | {
      insertion_anchor: ClipboardTrackInsertion;
      kind: 'new';
      name: string;
      track_id: string;
      track_kind: SceneTrackKind;
    }
  | {
      kind: 'classic_above_source';
      name: string;
      /**
       * Reserved even if an existing track is chosen; must be a fresh ID.
       */
      new_track_id: string;
    };
  export type ClipboardTrackInsertion =
  | {
      kind: 'above';
      track_id: string;
    }
  | {
      kind: 'below';
      track_id: string;
    }
  | {
      kind: 'highest';
    };

  export interface PasteTimelineSelection {
  at: Time;
  clipboard: TimelineClipboard;
  expected_revision: string;
  idempotency_key: string;
  label: string;
  placements: ClipboardTrackPlacement[];
  project_id: string;
  sequence_id: string;
}
/**
 * Scene time. Paste preserves exact relative offsets and does not perform
 * media-import FPS/canvas updates or independent per-element frame snaps.
 */
  export interface Time {
  ticks: string;
  timebase: number;
}
  export interface TimelineClipboard {
  /**
   * Ordered fixed-revision references, never client-authored node payloads.
   */
  items: TimelineClipboardItem[];
  /**
   * Binds full elements and their exact resource records at the source.
   */
  selection_digest: string;
  source_project_id: string;
  source_revision: string;
  source_sequence_id: string;
}
  export interface TimelineClipboardItem {
  source_element_id: string;
  source_track_id: string;
  source_track_kind: SceneTrackKind;
}
  export interface ClipboardTrackPlacement {
  /**
   * Exactly the copied members of this source track, in clipboard order.
   */
  elements: ClipboardElementIdentity[];
  source_track_id: string;
  target: ClipboardTrackTarget;
}
  export interface ClipboardElementIdentity {
  new_element_id: string;
  source_element_id: string;
}

}

